import{_ as s,o as n,c as e,a2 as t}from"./chunks/framework.CNQbXYGB.js";const g=JSON.parse('{"title":"第 3 章：存储体系、合并访存与异步等待机制","description":"","frontmatter":{},"headers":[],"relativePath":"03-memory/memory-hierarchy.md","filePath":"03-memory/memory-hierarchy.md"}'),l={name:"03-memory/memory-hierarchy.md"};function p(i,a,o,r,c,d){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="第-3-章-存储体系、合并访存与异步等待机制" tabindex="-1">第 3 章：存储体系、合并访存与异步等待机制 <a class="header-anchor" href="#第-3-章-存储体系、合并访存与异步等待机制" aria-label="Permalink to &quot;第 3 章：存储体系、合并访存与异步等待机制&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">小白速读：先用大白话理解这一章</p><p>数据放在哪里，速度天差地别：<strong>寄存器（VGPR/SGPR）</strong> 是手边的草稿纸（最快），<strong>LDS</strong> 是车间内的公共黑板（~60 周期，但 32 个人同时写同一列会“撞车”产生 Bank Conflict），<strong>L1/L2 Cache</strong> 是楼层和园区中转柜，<strong>HBM 显存</strong> 是楼下大仓库（要等 ~400 周期）。聪明的操作是：大家排好队一次拉一车整箱货（<strong>合并访存 + <code>float4</code></strong>），并且一边等仓库送货、一边先算手头的活（<strong><code>s_waitcnt</code> 异步重叠</strong>）。</p></div><h2 id="四、vgpr、sgpr、lds、cache、hbm-的关系" tabindex="-1">四、VGPR、SGPR、LDS、Cache、HBM 的关系 <a class="header-anchor" href="#四、vgpr、sgpr、lds、cache、hbm-的关系" aria-label="Permalink to &quot;四、VGPR、SGPR、LDS、Cache、HBM 的关系&quot;">​</a></h2><p>GPU 的另一个核心问题是数据如何存储、访问和复用。</p><p>可以把这些存储资源分为两类：</p><p><strong>软件显式使用的存储资源：</strong> 寄存器、LDS、全局内存。</p><p><strong>硬件缓存与访存体系：</strong> L1、L2、Memory Controller 等。</p><h3 id="_4-1-vgpr-向量寄存器" tabindex="-1">4.1 VGPR：向量寄存器 <a class="header-anchor" href="#_4-1-vgpr-向量寄存器" aria-label="Permalink to &quot;4.1 VGPR：向量寄存器&quot;">​</a></h3><p>VGPR（Vector General Purpose Register）用于保存向量运算数据。</p><p>对于一个 Wavefront，不同 Lane 通常拥有各自的 VGPR 值。</p><p>例如：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> input[idx];</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>编译器可能把 a、b 保存到 VGPR 中。</p><p>VGPR 常用于：</p><ul><li>向量计算的输入与输出。</li><li>GEMM 中的矩阵片段。</li><li>中间累加结果。</li><li>Thread 私有的临时变量。</li><li>部分地址计算结果。</li></ul><p><strong>VGPR 的优化核心是控制寄存器压力。</strong></p><p>如果一个 Kernel 每 Thread 需要大量 VGPR，就会占用更多硬件寄存器资源，可能减少能够同时驻留的 Wavefront。</p><p>如果寄存器需求超过可用范围，编译器可能把部分数据溢出到 Scratch Memory。</p><p>Scratch 虽然用于保存线程私有数据，但通常由显存体系承载，访问成本远高于寄存器。</p><h3 id="_4-2-sgpr-标量寄存器" tabindex="-1">4.2 SGPR：标量寄存器 <a class="header-anchor" href="#_4-2-sgpr-标量寄存器" aria-label="Permalink to &quot;4.2 SGPR：标量寄存器&quot;">​</a></h3><p>SGPR（Scalar General Purpose Register）主要保存 Wavefront 级别共享的标量值。</p><p>典型用途：</p><ul><li>Kernel 参数。</li><li>部分基地址。</li><li>循环控制变量。</li><li>Wave-uniform 标量计算结果。</li></ul><p>SGPR 和 VGPR 的核心差别：</p><table tabindex="0"><thead><tr><th>对比</th><th>VGPR</th><th>SGPR</th></tr></thead><tbody><tr><td>逻辑数据范围</td><td>不同 Lane 可以有不同值</td><td>通常保存 Wave-uniform 值</td></tr><tr><td>主要执行路径</td><td>VALU、向量访存、部分矩阵计算</td><td>SALU、标量操作</td></tr><tr><td>主要用途</td><td>每线程数据、矩阵片段、累加结果</td><td>地址、参数、循环控制</td></tr><tr><td>性能影响</td><td>寄存器压力、Occupancy、Spill</td><td>标量资源限制、指令效率</td></tr></tbody></table><p>需要注意，程序变量具体映射到哪种寄存器，由编译器的数据流分析和目标指令决定，并不完全取决于源代码变量类型。</p><h3 id="_4-3-lds-片上共享存储" tabindex="-1">4.3 LDS：片上共享存储 <a class="header-anchor" href="#_4-3-lds-片上共享存储" aria-label="Permalink to &quot;4.3 LDS：片上共享存储&quot;">​</a></h3><p>LDS（Local Data Share）是一种由软件显式管理的高速片上存储。</p><p>在 HIP 中通常通过 <code>__shared__</code> 声明数据。</p><p>例如：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">__shared__ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tile[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>它可以被同一 Block 的多个 Thread 使用。</p><p>LDS 最重要的两个用途：</p><p><strong>1. 数据复用</strong></p><p>多个线程需要使用相同的数据时，可以先从 Global Memory 加载到 LDS，再由多个线程重复读取。</p><p>例如 GEMM 中的 A/B Tile。</p><p><strong>2. 线程间通信</strong></p><p>一个 Thread 可以向 LDS 写入数据，另一个 Thread 在适当同步后读取。</p><p>例如 Reduction、Transpose 和 LSTM 中间状态共享。</p><p>LDS 属于 CU 级物理资源，但数据的逻辑共享范围通常是单个 Workgroup。</p><p>多个同时驻留在同一个 CU 上的 Block，可以使用同一个物理 LDS 容量的不同分配区域，但不能因此直接共享数据。</p><h3 id="_4-4-lds-bank-conflict" tabindex="-1">4.4 LDS Bank Conflict <a class="header-anchor" href="#_4-4-lds-bank-conflict" aria-label="Permalink to &quot;4.4 LDS Bank Conflict&quot;">​</a></h3><p>LDS 通常由多个 Bank 组成，以提高并行访问能力。</p><p>不同线程访问不同 Bank 时，可能并行完成访问。</p><p>当多个访问集中到同一个 Bank，且硬件无法合并为广播等特殊操作时，就可能发生 Bank Conflict。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>理想访问：</span></span>
<span class="line"><span>Lane 0 → Bank 0</span></span>
<span class="line"><span>Lane 1 → Bank 1</span></span>
<span class="line"><span>Lane 2 → Bank 2</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>冲突访问：</span></span>
<span class="line"><span>Lane 0 → Bank 0</span></span>
<span class="line"><span>Lane 1 → Bank 0</span></span>
<span class="line"><span>Lane 2 → Bank 0</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>实际 Bank 映射与地址、访问宽度和硬件规则有关。在常见的 AMD/DCU 架构中，LDS 通常划分为 <strong>32 个 Bank，每个 Bank 宽度为 4 字节（32-bit / 1 DWORD）</strong>：</p><p>\\text{Bank ID} = \\left\\lfloor \\frac{\\text{Byte Address}}{4} \\right\\rfloor \\bmod 32</p><p>理解这个公式能直接解释许多常见现象：</p><ul><li><strong>32-bit 访存（如 <code>ds_read_b32</code>）：</strong> 相邻线程访问连续的 <code>float</code>（步长 4B）时，依次落入 Bank 0~31，无冲突；但如果步长是 32 的倍数（例如对 <code>float tile[32][32]</code> 按列读取），所有线程落入同一个 Bank，引发 <strong>32-way Bank Conflict</strong>，吞吐骤降至 1/32。</li><li><strong>Broadcast（广播）：</strong> 多个线程读取<strong>完全相同的地址</strong>时，硬件通常能合并为单次读取并广播给所有请求线程，不构成 Bank Conflict。</li><li><strong>宽指令访存（<code>ds_read_b64</code> / <code>ds_read_b128</code>）：</strong> 单个线程一次读取 8B 或 16B 时会同时占用 2 个或 4 个连续 Bank；此时一个 Wavefront 往往拆成多个子周期（例如每 16 个或 8 个 Lane 一批）服务，只要同一批次内没有多个 Lane 撞到同一 Bank 即可无冲突。</li></ul><p>常见的 LDS 优化方法包括：</p><ul><li>Padding（例如将 <code>__shared__ float tile[32][32]</code> 改为 <code>tile[32][33]</code>，错开列方向的 Bank 对齐）。</li><li>Swizzle Layout（通过异或 <code>row ^ col</code> 重排存储索引，在不浪费额外 LDS 容量的前提下消除冲突，在 FlashAttention / GEMM 中极为常用）。</li><li>调整数据排列方式与向量化读写粒度。</li><li>改变线程与数据的对应关系。</li><li>减少不必要的 LDS 访问（能用寄存器 Shuffle 解决的就不进 LDS）。</li></ul><p>这也是为什么两个数学运算完全相同的 GEMM Kernel，可能仅因 LDS Layout 不同就产生明显性能差异。</p><h3 id="_4-5-cache-l1、l2-与全局内存合并访问-coalescing" tabindex="-1">4.5 Cache：L1、L2 与全局内存合并访问（Coalescing） <a class="header-anchor" href="#_4-5-cache-l1、l2-与全局内存合并访问-coalescing" aria-label="Permalink to &quot;4.5 Cache：L1、L2 与全局内存合并访问（Coalescing）&quot;">​</a></h3><p>GPU Cache 主要用于降低对更远端存储的访问成本。</p><p>一般可以理解为：</p><ul><li><strong>Vector L1（TCP）：</strong> 靠近计算单元（通常 CU 私有或紧邻 CU），服务局部向量访存请求；<strong>需要注意的是，不同 CU 的 L1 Cache 之间通常不自动维护硬件一致性</strong>，因此跨 Block 通信（如全局原子操作、Persistent Kernel 标志位轮询）需要通过绕过 L1（如 <code>glc</code> / <code>slc</code> 缓存策略或 <code>atomic</code> 指令）直接与 L2 交互。</li><li><strong>L2（TCC）：</strong> 覆盖更大范围，由多个 CU 共享，是所有全局访存和原子操作的一级一致性汇聚点。</li><li><strong>HBM：</strong> 保存模型权重、激活、KV Cache 和其他全局数据。</li></ul><p>但不同 DCU 型号中 L1/L2 的实际结构、容量、Cache Line 大小和一致性机制需要通过实测或芯片手册分别确认。</p><p>LDS 和 Cache 的区别是：</p><p><strong>LDS 主要由程序显式管理，Cache 主要由硬件缓存机制管理。</strong></p><p>使用 LDS 不代表所有数据都必须经过 L1/L2，也不代表所有 Kernel 都需要先将数据复制到 LDS。</p><h4 id="合并访存-memory-coalescing-与向量化访存" tabindex="-1">合并访存（Memory Coalescing）与向量化访存 <a class="header-anchor" href="#合并访存-memory-coalescing-与向量化访存" aria-label="Permalink to &quot;合并访存（Memory Coalescing）与向量化访存&quot;">​</a></h4><p>理解全局内存（HBM / L2 / L1）性能的关键在于 <strong>Memory Coalescing</strong>：</p><ul><li>当一个 Wavefront（64 个 Lane）执行一次全局加载指令时，硬件内存控制器会将这 64 个 Lane 的请求地址按 <strong>Cache Line 粒度（常见为 64B 或 128B）</strong> 进行合并。</li><li><strong>合并访问（Coalesced）：</strong> 如果 Lane 0~63 访问连续的 64 个 <code>float</code>（共 256 字节），硬件只需发起极少数连续的 Cache Line 事务即可满足整个 Wavefront，带宽利用率极高。</li><li><strong>非合并/跨步访问（Uncoalesced / Strided）：</strong> 如果相邻 Lane 访问步长很大的地址（例如按列访问行主序大矩阵），64 个请求可能分散到 64 个不同的 Cache Line 中，导致有效数据只占实际搬运字节的几分之一，带宽被严重浪费。</li><li><strong>向量化访存（<code>float4</code> / <code>dwordx4</code>）：</strong> 让单个线程一次加载 128-bit（4 个 <code>float</code>），不仅能将访存指令数减少为 1/4、降低指令发射压力，还能更容易凑满连续的高效内存事务。</li></ul><h3 id="_4-6-hbm-全局显存" tabindex="-1">4.6 HBM：全局显存 <a class="header-anchor" href="#_4-6-hbm-全局显存" aria-label="Permalink to &quot;4.6 HBM：全局显存&quot;">​</a></h3><p>HBM 用于保存大容量模型数据，是大模型推理中非常重要的硬件资源。</p><p>典型数据包括：</p><ul><li>模型权重。</li><li>输入输出 Tensor。</li><li>中间激活。</li><li>KV Cache。</li><li>多个 Kernel 之间传递的数据。</li></ul><p>HBM 的两个重要性能指标：</p><p><strong>带宽：</strong> 单位时间能够传输多少数据。</p><p><strong>延迟：</strong> 一次数据访问从发起到获得结果需要多长时间。</p><p>高带宽不等于低延迟。</p><p>GPU 通过大量并行访存请求、缓存复用及 Wavefront 调度等机制提高整体有效吞吐。</p><h3 id="_4-7-vmem-与数据搬运单元" tabindex="-1">4.7 VMEM 与数据搬运单元 <a class="header-anchor" href="#_4-7-vmem-与数据搬运单元" aria-label="Permalink to &quot;4.7 VMEM 与数据搬运单元&quot;">​</a></h3><p>除了计算单元，还要理解访存指令的执行路径。</p><p>在 AMD 风格架构中，常见的逻辑分类包括：</p><ul><li>VMEM：向量内存访问。</li><li>SMEM：标量内存访问。</li><li>LDS/DS：本地共享存储访问。</li><li>Cache 与内存控制器：处理缓存请求和外部显存访问。</li></ul><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Global Memory Load</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>VMEM 访存请求</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>L1 / L2 / HBM</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>数据返回寄存器</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>VALU / MMAC 消费数据</span></span></code></pre></div><p>而当程序使用 LDS 时，通常还会涉及：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Global Memory</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>加载到寄存器</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>写入 LDS</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>同步 / 等待数据就绪</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>从 LDS 读取矩阵片段</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>MMAC 计算</span></span></code></pre></div><p>部分架构支持专门的数据搬运机制，可以缩短或优化上述路径。</p><h4 id="异步访存与-s-waitcnt-硬件同步机制" tabindex="-1">异步访存与 <code>s_waitcnt</code> 硬件同步机制 <a class="header-anchor" href="#异步访存与-s-waitcnt-硬件同步机制" aria-label="Permalink to &quot;异步访存与 \`s_waitcnt\` 硬件同步机制&quot;">​</a></h4><p>理解计算与访存重叠（Overlap）的关键在于：<strong>GPU 的访存指令（VMEM、LDS、SMEM）通常是异步发射的</strong>。</p><p>当 Wavefront 发射一条 <code>global_load</code> 或 <code>ds_read</code> 指令后，硬件并不会立刻阻塞该 Wavefront，而是增加对应的未完成访存计数器，并允许 Wavefront 继续发射后续<strong>不依赖该数据</strong>的独立指令（如地址计算、上一轮 Tile 的 MMAC 计算）。直到真正需要消费该寄存器结果的指令之前，编译器会插入 <code>s_waitcnt</code> 指令进行显式等待：</p><ul><li><code>vmcnt(k)</code>：等待未完成的 <strong>VMEM</strong>（全局显存/L1/L2）指令数量降到 <code>k</code> 及以下。</li><li><code>lgkmcnt(k)</code>：等待未完成的 <strong>LDS / SMEM</strong> 指令数量降到 <code>k</code> 及以下。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Software Pipelining（双缓冲重叠）在指令流上的本质：</span></span>
<span class="line"><span>1. 发射第 k+1 轮的 global_load  → vmcnt 变为 1（不阻塞）</span></span>
<span class="line"><span>2. 执行第 k 轮的 MMAC 计算       → 趁数据在路上时占满矩阵单元！</span></span>
<span class="line"><span>3. s_waitcnt vmcnt(0)           → 此时数据大概率已到达，等待时间极短</span></span>
<span class="line"><span>4. 进入第 k+1 轮计算</span></span></code></pre></div><p>如果在 Profiler 中看到某个 Kernel 有大量的 <code>Waitcnt Stall</code>，往往意味着 <code>vmcnt</code> 或 <code>lgkmcnt</code> 阻塞时间过长——要么是驻留 Wavefront 太少（TLP 不足），要么是单 Wave 内部独立指令不够（ILP / 双缓冲预取不足）。</p><p>具体采用什么路径，需要查看目标 ISA 和实际生成的指令。</p><h3 id="_4-8-wavefront-内跨-lane-通信-shuffle-dpp-与-lds-的取舍" tabindex="-1">4.8 Wavefront 内跨 Lane 通信（Shuffle / DPP）与 LDS 的取舍 <a class="header-anchor" href="#_4-8-wavefront-内跨-lane-通信-shuffle-dpp-与-lds-的取舍" aria-label="Permalink to &quot;4.8 Wavefront 内跨 Lane 通信（Shuffle / DPP）与 LDS 的取舍&quot;">​</a></h3><p>在 4.3 节我们提到同一个 Block 内可以通过 LDS 交换数据，但如果只需要在<strong>同一个 Wavefront（64 个 Lane）内部</strong>交换数据（例如 Softmax / RMSNorm 中的 Max / Sum Reduction），往往有更快的硬件路径：</p><ul><li><strong>HIP 原语：</strong> <code>__shfl_down</code>、<code>__shfl_xor</code>、<code>__shfl_up</code>、<code>__shfl</code>。</li><li><strong>底层硬件机制：</strong> 编译器通常会将其映射为寄存器级的 <strong>DPP（Data Parallel Primitives）</strong> 或 <code>ds_bpermute</code> / <code>v_perm</code> 类指令，直接在 SIMD 通道或极轻量级交叉开关上完成 Lane 间寄存器值传递。</li></ul><table tabindex="0"><thead><tr><th>对比维度</th><th>寄存器级 Shuffle / DPP</th><th>LDS (<code>__shared__</code>) + <code>__syncthreads()</code></th></tr></thead><tbody><tr><td>通信范围</td><td>仅限同一 Wavefront 内（64 Lane）</td><td>整个 Block 内（跨 Wavefront）</td></tr><tr><td>延迟与开销</td><td>极低（无需写回 LDS，无需全 Block Barrier）</td><td>较高（需 LDS 读写 + <code>lgkmcnt</code> + <code>s_barrier</code>）</td></tr><tr><td>典型场景</td><td>Wave 内规约（Reduction）、局部数据重排</td><td>跨 Wave 规约、GEMM Tile 共享、矩阵转置</td></tr></tbody></table><p>因此，在编写 Reduction 或 Attention Softmax 时，标准做法是 <strong>“先在 Wave 内用 <code>__shfl_down</code> / <code>__shfl_xor</code> 规约到 Lane 0，再仅由各 Wave 的 Lane 0 写入 LDS 做跨 Wave 汇总”</strong>，这样可以大幅削减 LDS 访问和同步开销。</p><hr>`,96)])])}const k=s(l,[["render",p]]);export{g as __pageData,k as default};
